	@always(inst, inst, inst, pcpaused)
	def select_ramc():	 
		# ternary:		  
		if (((inst[7+1:5] == 0b111) & (inst[3+1:2] == 0b00)) & (inst[1+1:0] != 0b01))  &  (pcpaused[0] == False):		 
			ramc.next = True
		else:
			ramc.next = False


